// Style lab · isometric low-poly city. Pure deterministic layout and timing: every value is a function of
// the frame, hashes replace randomness, nothing is generated by a model.
import {Easing} from "remotion";
import brand from "../../../video-design/brand.json";

export const C=brand.colors;
export const FPS=30,FRAMES=150;
export type V3=[number,number,number];
type V2=[number,number];

const fract=(v:number)=>v-Math.floor(v);
export const rnd=(n:number)=>fract(Math.sin(n*127.1+311.7)*43758.5453);
const r2=(a:number,b:number,k=0)=>rnd(a*92.17+b*31.73+k*17.31+.5);
export const clamp01=(x:number)=>Math.min(1,Math.max(0,x));
export const smooth=(x:number)=>{const t=clamp01(x);return t*t*(3-2*t);};
export const easeOut=Easing.bezier(.16,1,.3,1);
export const easeInOut=Easing.bezier(.65,0,.35,1);
export const tween=(t:number,a:number,b:number,ease:(x:number)=>number=easeOut)=>ease(clamp01((t-a)/(b-a)));

// True isometric elevation: the camera looks along (1,1,1) at azimuth 45°.
export const ELEV=Math.atan(1/Math.SQRT2);
export function camState(t:number){
 const k=easeInOut(clamp01(t/5));
 const az=(39+8*k)*Math.PI/180,zoom=44+4*k;
 const target:V3=[1.4,.4,-.5],d=80;
 const pos:V3=[target[0]+d*Math.cos(ELEV)*Math.sin(az),target[1]+d*Math.sin(ELEV),target[2]+d*Math.cos(ELEV)*Math.cos(az)];
 return {pos,target,zoom};
}

// Route on street centre lines (streets at 4k+2). The x=2 leg climbs onto an elevated deck.
const WAY:V2[]=[[6,11.2],[6,6],[2,6],[2,-6],[-2,-6],[-2,-11]];
const CORNER=.9;
export const DECK={x:2,z0:4.4,z1:2.4,z2:-2.4,z3:-4.4,h:1.35,width:.98};
export function deckLift(x:number,z:number){
 if(Math.abs(x-DECK.x)>1e-6)return 0;
 return DECK.h*smooth((DECK.z0-z)/(DECK.z0-DECK.z1))*smooth((z-DECK.z3)/(DECK.z2-DECK.z3));
}
function buildPath(){
 const pts:V2[]=[];
 const push=(p:V2)=>{const l=pts.at(-1);if(!l||Math.hypot(p[0]-l[0],p[1]-l[1])>1e-6)pts.push(p);};
 const line=(a:V2,b:V2)=>{const n=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/.08));for(let i=0;i<=n;i++)push([a[0]+(b[0]-a[0])*i/n,a[1]+(b[1]-a[1])*i/n]);};
 const unit=(a:V2,b:V2):V2=>{const l=Math.hypot(b[0]-a[0],b[1]-a[1]);return [(b[0]-a[0])/l,(b[1]-a[1])/l];};
 let cur=WAY[0];
 for(let i=1;i<WAY.length;i++){
  const p=WAY[i];
  if(i===WAY.length-1){line(cur,p);break;}
  const din=unit(WAY[i-1],p),dout=unit(p,WAY[i+1]);
  const a:V2=[p[0]-din[0]*CORNER,p[1]-din[1]*CORNER],b:V2=[p[0]+dout[0]*CORNER,p[1]+dout[1]*CORNER];
  line(cur,a);
  for(let k=1;k<=14;k++){const u=k/14;push([(1-u)**2*a[0]+2*(1-u)*u*p[0]+u*u*b[0],(1-u)**2*a[1]+2*(1-u)*u*p[1]+u*u*b[1]]);}
  cur=b;
 }
 const P=pts.map(([x,z])=>[x,deckLift(x,z),z] as V3);
 const S=[0];
 for(let i=1;i<P.length;i++)S.push(S[i-1]+Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1],P[i][2]-P[i-1][2]));
 return {P,S,L:S.at(-1)!};
}
export const PATH=buildPath();
export function posAt(s:number):V3{
 const {P,S,L}=PATH,v=Math.min(L,Math.max(0,s));
 let lo=0,hi=S.length-1;
 while(hi-lo>1){const m=(lo+hi)>>1;if(S[m]<=v)lo=m;else hi=m;}
 const f=(v-S[lo])/Math.max(1e-9,S[hi]-S[lo]);
 return [P[lo][0]+(P[hi][0]-P[lo][0])*f,P[lo][1]+(P[hi][1]-P[lo][1])*f,P[lo][2]+(P[hi][2]-P[lo][2])*f];
}
/** Position plus yaw (around +Y, forward = local +X) and pitch (around local Z). */
export function along(s:number){
 const p=posAt(s),a=posAt(s-.12),b=posAt(s+.12);
 const dx=b[0]-a[0],dy=b[1]-a[1],dz=b[2]-a[2],hz=Math.hypot(dx,dz)||1e-9;
 return {p,yaw:Math.atan2(-dz,dx),pitch:Math.atan2(dy,hz),side:[-dz/hz,dx/hz] as V2};
}
function sOnDeckLeg(z:number){
 const {P,S}=PATH;
 for(let i=0;i<P.length;i++)if(Math.abs(P[i][0]-DECK.x)<1e-6&&P[i][2]<=z)return S[i];
 throw new Error("deck leg sample missing");
}
export const ZONES={yellowIn:sOnDeckLeg(5),jamIn:sOnDeckLeg(2.4),jamOut:sOnDeckLeg(-2),yellowOut:sOnDeckLeg(-4.6),deckIn:sOnDeckLeg(DECK.z0+.1),deckOut:sOnDeckLeg(DECK.z3-.1)};
export function trafficMix(s:number){
 const k=.45;
 const y=smooth((s-ZONES.yellowIn)/k+.5)*(1-smooth((s-ZONES.yellowOut)/k+.5));
 const p=smooth((s-ZONES.jamIn)/k+.5)*(1-smooth((s-ZONES.jamOut)/k+.5));
 return {g:(1-y)*(1-p),y:y*(1-p),p};
}

// Timeline (seconds).
export const T={
 cityRise:[0,1.4],deckRise:[.3,.9],heroIn:[.55,1],card:[.35,.85],
 draw:[1,2.3],destIn:[2.05,2.6],sweep:[1.9,3.1],eta:[2.45,3.25],jamPill:[2.95,3.4],heroGo:1.45,
};
export const drawnS=(t:number)=>PATH.L*tween(t,T.draw[0],T.draw[1],easeInOut);
export const sweepS=(t:number)=>(PATH.L+2)*tween(t,T.sweep[0],T.sweep[1],easeInOut)-1;
export const sweepWeight=(s:number,t:number)=>smooth((sweepS(t)-s)/1.4+.5);

export const jamCarS=(k:number,t:number)=>ZONES.jamIn+.55+k*.78+.18*t;
export const JAM_CARS=5;
// Hero car: integrate a speed that follows the traffic under it, never closer than one car length to the queue.
export const HERO_S=(()=>{
 const s:number[]=[];let pos=0;
 for(let f=0;f<=FRAMES;f++){
  const t=f/FPS;s.push(pos);
  const m=trafficMix(pos),v=smooth((t-T.heroGo)/.55)*(4.3*m.g+1.5*m.y+.45*m.p);
  pos=Math.min(pos+v/FPS,Math.max(pos,jamCarS(0,t)-.85));
 }
 return s;
})();

export const START=posAt(0),DEST=posAt(PATH.L);

// ---- City layout -------------------------------------------------------------------------------
const STRIP={d:2,s:2.5,hw:22,hl:52};
const inStrip=(x:number,z:number,m=0)=>Math.abs(x-z-STRIP.d)<=STRIP.hw+m&&Math.abs(x+z-STRIP.s)<=STRIP.hl+m;
const STREETS=Array.from({length:31},(_,i)=>-58+i*4);

export type Building={x:number;z:number;w:number;d:number;h:number;hb:number;tw:number;td:number;color:string;delay:number};
export type Roof={b:number;x:number;z:number;s:number;h:number};
export type Window={b:number;x:number;y:number;z:number;len:number;face:"x"|"z";color:string};
export type Plate={x:number;z:number;park:boolean};
export type Tree={x:number;z:number;s:number;delay:number};
export type Dash={x:number;z:number;axis:"x"|"z"};

// Occlusion guard: a building may not hide any route point (ground or deck) from the camera.
// A point is hidden when the ray P + a·(√2·sinθ, 1, √2·cosθ) passes the footprint below the roof.
const GUARD=(()=>{
 const pts:V3[]=[];
 for(let s=0;s<=PATH.L;s+=.3){const {p,side}=along(s);for(const o of [-.45,0,.45])pts.push([p[0]+side[0]*o,p[1],p[2]+side[1]*o]);}
 for(let y=0;y<=1.5;y+=.25)pts.push([DEST[0],y,DEST[2]]);
 return pts;
})();
const RAYS=[37,43,49].map(a=>[Math.SQRT2*Math.sin(a*Math.PI/180),Math.SQRT2*Math.cos(a*Math.PI/180)]);
function occlusionCap(x0:number,x1:number,z0:number,z1:number){
 const m=.22;let cap=Infinity;
 for(const [dx,dz] of RAYS)for(const p of GUARD){
  const lo=Math.max(0,(x0-m-p[0])/dx,(z0-m-p[2])/dz),hi=Math.min((x1+m-p[0])/dx,(z1+m-p[2])/dz);
  if(lo<=hi)cap=Math.min(cap,p[1]+lo);
 }
 return cap;
}
const BUILDING_COLORS=["#2A2536","#252131","#302A3D","#211C2C","#383145","#2D2738"];

export const CITY=(()=>{
 const buildings:Building[]=[],roofs:Roof[]=[],windows:Window[]=[],plates:Plate[]=[],trees:Tree[]=[],dashes:Dash[]=[];
 const delayAt=(x:number,z:number,j:number)=>.04+.72*clamp01(Math.hypot(x-2,z)/26)+.08*j;
 for(let i=-20;i<=20;i++)for(let j=-20;j<=20;j++){
  const cx=4*i,cz=4*j;
  if(!inStrip(cx,cz))continue;
  const p=r2(i,j,1),park=p<.08;
  plates.push({x:cx,z:cz,park});
  if(park){
   const n=5+Math.floor(r2(i,j,9)*5);
   for(let k=0;k<n;k++)trees.push({x:cx+(r2(i,j,20+k)-.5)*2.3,z:cz+(r2(i,j,40+k)-.5)*2.3,s:.7+.45*r2(i,j,60+k),delay:delayAt(cx,cz,r2(i,j,80+k))});
   continue;
  }
  const along=r2(i,j,2)<.5;
  const lots:{x:number;z:number;w:number;d:number}[]=[];
  const half=(o:number)=>along?{x:cx,z:cz+o,w:2.7,d:1.3}:{x:cx+o,z:cz,w:1.3,d:2.7};
  const q=(ox:number,oz:number)=>({x:cx+ox,z:cz+oz,w:1.3,d:1.3});
  if(p<.3)lots.push({x:cx,z:cz,w:2.7,d:2.7});
  else if(p<.55)lots.push(half(-.7),half(.7));
  else if(p<.8)lots.push(q(-.7,-.7),q(.7,-.7),q(-.7,.7),q(.7,.7));
  else lots.push(half(-.7),...(along?[q(-.7,.7),q(.7,.7)]:[q(.7,-.7),q(.7,.7)]));
  for(const lot of lots){
   const k=lot.x*3.17+lot.z*1.13;
   const w=lot.w*(.84+.1*rnd(k+1)),d=lot.d*(.84+.1*rnd(k+2));
   const cap=occlusionCap(lot.x-w/2,lot.x+w/2,lot.z-d/2,lot.z+d/2);
   let h=.35+.95*rnd(k+3)**2;
   if(rnd(k+4)<.24)h=1.7+1.9*rnd(k+5);
   h=Math.max(.16,Math.min(h,cap));
   const tier=h>1.5&&rnd(k+6)<.6,hb=tier?h*.76:h;
   const b=buildings.length;
   buildings.push({x:lot.x,z:lot.z,w,d,h,hb,tw:tier?w*.62:0,td:tier?d*.62:0,color:BUILDING_COLORS[Math.floor(rnd(k+7)*BUILDING_COLORS.length)],delay:delayAt(lot.x,lot.z,rnd(k+8))});
   if(cap-h>.14&&rnd(k+9)<.6){
    const tw=tier?w*.62:w,td=tier?d*.62:d,n=1+Math.floor(rnd(k+10)*2);
    for(let u=0;u<n;u++)roofs.push({b,x:lot.x+(rnd(k+11+u)-.5)*tw*.5,z:lot.z+(rnd(k+13+u)-.5)*td*.5,s:.14+.12*rnd(k+15+u),h:.06+.06*rnd(k+17+u)});
   }
   if(hb>.7)for(let y=.26,row=0;y<hb-.12;y+=.24,row++)for(const face of ["x","z"] as const){
    const r=rnd(k+31+row*2.7+(face==="x"?0:.9));
    const color=r<.83?"#3A2F54":r<.95?"#7C68AC":"#BFA04A";
    windows.push(face==="x"?{b,x:lot.x+w/2+.006,y,z:lot.z,len:d*.74,face,color}:{b,x:lot.x,y,z:lot.z+d/2+.006,len:w*.74,face,color});
   }
  }
 }
 for(const c of STREETS)for(const axis of ["x","z"] as const){
  for(let u=-60;u<=60;u+=1){
   if(STREETS.some(s=>Math.abs(u-s)<.8))continue;
   const x=axis==="x"?u:c,z=axis==="x"?c:u;
   if(inStrip(x,z,-1))dashes.push({x,z,axis});
  }
 }
 return {buildings,roofs,windows,plates,trees,dashes};
})();

// ---- Background traffic --------------------------------------------------------------------------
// Cars never pop: they shrink in/out over the last metre of a lane that ends outside the frame.
const ROUTE_STREETS={x:[6,2,-2],z:[6,-6]};
export type Car={axis:"x"|"z";c:number;dir:1|-1;min:number;len:number;o:number;v:number;color:string};
const CAR_COLORS=["#3A3346","#2C2D28","#4A4060","#FDFEED","#8D59DA","#F4CA50","#3A3346","#E0CDF8"];
export const CARS=(()=>{
 const cars:Car[]=[];
 for(const c of STREETS)for(const axis of ["x","z"] as const){
  if((axis==="x"?ROUTE_STREETS.z:ROUTE_STREETS.x).includes(c))continue;
  // street along X has constant z=c, and vice versa
  let lo=Infinity,hi=-Infinity;
  for(let u=-70;u<=70;u+=.5){const x=axis==="x"?u:c,z=axis==="x"?c:u;if(inStrip(x,z,-2)){lo=Math.min(lo,u);hi=Math.max(hi,u);}}
  if(!(hi-lo>6))continue;
  for(const dir of [1,-1] as const){
   const n=1+Math.floor(r2(c,dir,axis==="x"?3:4)*2);
   for(let k=0;k<n;k++)cars.push({axis,c,dir,min:lo,len:hi-lo,o:fract(r2(c,dir,10+k)+k/n),v:1.3+1.2*r2(c,dir,20+k),color:CAR_COLORS[Math.floor(r2(c,dir,30+k)*CAR_COLORS.length)]});
  }
 }
 return cars;
})();
export function carState(car:Car,t:number){
 const u=fract(car.o+car.v*t/car.len)*car.len,coord=car.dir>0?car.min+u:car.min+car.len-u;
 const lane=.23*car.dir;
 const x=car.axis==="x"?coord:car.c-lane,z=car.axis==="x"?car.c+lane:coord;
 const yaw=car.axis==="x"?(car.dir>0?0:Math.PI):(car.dir>0?-Math.PI/2:Math.PI/2);
 return {x,z,yaw,s:smooth(u/1.2)*smooth((car.len-u)/1.2)};
}
